import{_ as a,a as t,b as o,c as r}from"./chunks/Variant._HIU2fAQ.js";import{_ as s,o as n,c as i,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Download","description":"","frontmatter":{},"headers":[],"relativePath":"install/download.md","filePath":"install/download.md"}'),d={name:"install/download.md"};function h(p,e,u,c,m,f){return n(),i("div",null,[...e[0]||(e[0]=[l('<h2 id="which-one-to-install" tabindex="-1">Which one to install? <a class="header-anchor" href="#which-one-to-install" aria-label="Permalink to &quot;Which one to install?&quot;">​</a></h2><p>xDrip is not available in the Google Play store. You will find all releases in <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">Github</a>.<br> You have two main choices when installing xDrip, either install the <strong>Latest release</strong> or a <strong>Pre-release</strong>.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you already have xDrip installed on your phone you don&#39;t need to uninstall it before installing an update.<br> If you use a forked version and want to change xDrip to an official release, or vice versa, follow <a href="./../troubleshoot/reinstall.html">this</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Multiple xDrip installation</p><p>If you need to install more than one xDrip on the same phone you need a <a href="#variants">variant</a>.</p></div><h3 id="latest-release" tabindex="-1">Latest release <a class="header-anchor" href="#latest-release" aria-label="Permalink to &quot;Latest release&quot;">​</a></h3><p>Latest release is a stable version of xDrip. It doesn&#39;t have all the newest features but has proven stability and doesn&#39;t suffer from severe bugs. It&#39;s a safe version to start with unless you need a specific feature (see the <a href="./../changelog.html">change log</a> to check).</p><p>You can download it from <a href="https://xdrip-plus-updates.appspot.com/stable/xdrip-plus-latest.apk" target="_blank" rel="noreferrer">here</a> or follow this QR code:</p><img src="https://jamorham.github.io/images/download-xdrip-plus-qr-code-120.png"><p>You will also find it in the <a href="https://github.com/NightscoutFoundation/xDrip" target="_blank" rel="noreferrer">main repository</a> selecting Latest.</p><img src="'+a+'" style="zoom:50%;"><br><h4 id="download-warning" tabindex="-1">Download warning <a class="header-anchor" href="#download-warning" aria-label="Permalink to &quot;Download warning&quot;">​</a></h4><p>xDrip downloaded from <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">https://github.com/NightscoutFoundation/xDrip/releases</a> is safe.</p><img src="'+t+'" style="zoom:75%;"><br><p>Once downloaded, <a href="./install.html">Proceed to installing xDrip</a></p><br><h3 id="pre-release" tabindex="-1">Pre-release <a class="header-anchor" href="#pre-release" aria-label="Permalink to &quot;Pre-release&quot;">​</a></h3><p>Pre-releases include the most recent xDrip developments like translations, new features and bug fixes. And they might also contain some bugs... Still, it is the version you want to use to benefit from the most recent improvements.</p><p>All xDrip versions are available <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">here</a>.</p><p>Expand the assets and select the <code>.apk</code> file. You will find it in your phone&#39;s <code>Downloads</code> directory.</p><img src="'+o+'" style="zoom:50%;"><div class="info custom-block"><p class="custom-block-title">Note</p><p>Do <strong>not</strong> use Facebook links to download xDrip but <strong>copy and paste the link</strong> into a browser (like Chrome).</p></div><br><h4 id="download-warning-1" tabindex="-1">Download warning <a class="header-anchor" href="#download-warning-1" aria-label="Permalink to &quot;Download warning&quot;">​</a></h4><p>xDrip downloaded from <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">https://github.com/NightscoutFoundation/xDrip/releases</a> is safe.</p><img src="'+t+'" style="zoom:75%;"><br><p>Once downloaded, <a href="./install.html">Proceed to installing xDrip</a></p><br><h2 id="forked-versions" tabindex="-1">Forked versions <a class="header-anchor" href="#forked-versions" aria-label="Permalink to &quot;Forked versions&quot;">​</a></h2><p>Some developers add features and customizations that are not available in the official pre-releases until the author creates a Pull Request in xDrip and get it merged in the main project.</p><div class="warning custom-block"><p class="custom-block-title">Updating forked versions</p><p>You can use these versions but need to understand they might be supported only by their creator.<br><strong>xDrip automatic updates won&#39;t work with forked versions.</strong><br> Also keep in mind you cannot install a forked version if you have an official version installed on your phone:<br> you will need to <a href="./../troubleshoot/reinstall.html">uninstall</a> it first.<br> The same applies for the other way round (from forked to official).</p></div><br><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><p>Four variants are regularly released to allow a total of 5 xDrip being installed on your phone. This can prove particularly useful to follow more than one person at a time.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>It is not recommended to use a variant connected to your sensor: use the main release only.<br> Only use variants for followers.<br> Some early versions of xDrip leaked values when using AAPS/NSClient. Use the latest variants.</p></div><p>You can download variants <a href="https://drive.google.com/drive/folders/0B6mvYVNVC-fOWkxnVF80dlFabjQ?resourcekey=0-ebguuiPuB1wUI9Rp2zjMNg" target="_blank" rel="noreferrer">here</a>.</p><p>Sort them by last modified first and choose the variant to download.</p><img src="'+r+'" style="zoom:90%;"><p>Variants are also bundled as assets alongside the regular apk in the latest release on <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">GitHub</a>.</p><img src="'+a+'" style="zoom:50%;"><p>Once you have downloaded a variant, proceed like a normal xDrip install.</p><p><strong>Variants don&#39;t update automatically.</strong> You need to download and install updates on top of the current variant version (you don&#39;t need to uninstall it); just make sure you select the same variant (1 to 4).</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.02.26" target="_blank" rel="noreferrer"><em>Last modified 3/2/2023</em></a></p>',46)])])}const w=s(d,[["render",h]]);export{v as __pageData,w as default};
